#!/usr/bin/env bash
# Generate slo/generated/prometheus-rules.yaml from slo/backend-api-slo.yaml with the real Sloth CLI,
# then wrap the plain rule groups in a PrometheusRule so the Prometheus Operator loads them.
set -euo pipefail
cd "$(dirname "$0")/.."
RULES=$(docker run --rm -v "$PWD/slo:/slo:ro" ghcr.io/slok/sloth:v0.11.0 generate -i /slo/backend-api-slo.yaml)
{
  cat <<HEADER
# GENERATED by scripts/gen-slo.sh (sloth v0.11.0). Do not edit; edit slo/backend-api-slo.yaml and regenerate.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: backend-api-slo
  namespace: monitoring
spec:
HEADER
  echo "$RULES" | grep -v '^---$' | sed 's/^/  /'
} > slo/generated/prometheus-rules.yaml
echo "wrote slo/generated/prometheus-rules.yaml"
